import pulp

# Data from the problem
phases_data = {
    1: [(4, 5), (5, 3), (1, 6), (3, 2), (2, 3), (6, 1), (7, 3)],
    2: [(5, 2), (7, 8), (2, 9), (1, 6), (4, 6), (6, 2), (3, 1)],
    3: [(2, 8), (7, 6), (4, 9), (3, 6), (6, 2), (1, 2), (5, 5)],
    4: [(5, 5), (4, 4), (2, 8), (3, 6), (7, 5), (1, 7), (6, 10)],
    5: [(2, 6), (1, 6), (4, 7), (3, 5), (5, 6), (7, 7), (6, 5)],
    6: [(7, 6), (1, 4), (4, 3), (3, 6), (6, 8), (2, 4), (5, 2)],
    7: [(6, 7), (4, 9), (7, 5), (5, 8), (3, 4), (2, 6), (1, 9)],
}

# Model
model = pulp.LpProblem("Construction_Project_Scheduling", pulp.LpMinimize)

# Decision variables
S = {}  # Start times
for p in range(1, 8):
    for o in range(1, 8):
        S[(p, o)] = pulp.LpVariable(f"S_{p}_{o}", lowBound=0, cat='Continuous')

C_max = pulp.LpVariable("C_max", lowBound=0, cat='Continuous')

# Big M: sum of all durations
M = 0
for p in range(1, 8):
    for o in range(1, 8):
        M += phases_data[p][o-1][1]

# Binary variables for sequencing on same team
y = {}
for p in range(1, 8):
    for o in range(1, 8):
        for p2 in range(1, 8):
            for o2 in range(1, 8):
                if (p, o) >= (p2, o2):
                    continue
                team1 = phases_data[p][o-1][0]
                team2 = phases_data[p2][o2-1][0]
                if team1 == team2:
                    y[(p, o, p2, o2)] = pulp.LpVariable(
                        f"y_{p}_{o}_{p2}_{o2}", cat='Binary'
                    )

# Objective: minimize makespan
model += C_max

# Constraints 1: Precedence within each phase
for p in range(1, 8):
    for o in range(1, 7):
        model += (
            S[(p, o)] + phases_data[p][o-1][1] <= S[(p, o+1)],
            f"Precedence_phase{p}_op{o}_to_{o+1}"
        )

# Constraints 2: Machine capacity (disjunctive constraints)
for p in range(1, 8):
    for o in range(1, 8):
        for p2 in range(1, 8):
            for o2 in range(1, 8):
                if (p, o) >= (p2, o2):
                    continue
                team1 = phases_data[p][o-1][0]
                team2 = phases_data[p2][o2-1][0]
                if team1 == team2:
                    # If y = 1, then (p,o) before (p2,o2)
                    model += (
                        S[(p, o)] + phases_data[p][o-1][1] <= S[(p2, o2)] + M * (1 - y[(p, o, p2, o2)]),
                        f"Disj1_{p}_{o}_{p2}_{o2}"
                    )
                    # If y = 0, then (p2,o2) before (p,o)
                    model += (
                        S[(p2, o2)] + phases_data[p2][o2-1][1] <= S[(p, o)] + M * y[(p, o, p2, o2)],
                        f"Disj2_{p}_{o}_{p2}_{o2}"
                    )

# Constraints 3: Makespan definition
for p in range(1, 8):
    model += (
        S[(p, 7)] + phases_data[p][6][1] <= C_max,
        f"Makespan_phase{p}"
    )

# Solve
solver = pulp.HiGHS(msg=False, timeLimit=120)
model.solve(solver)

# Output
print("Status:", pulp.LpStatus[model.status])
print("Optimal makespan:", pulp.value(C_max))
print("\nStart times for each phase operation:")
for p in range(1, 8):
    print(f"Phase {p}:", end=" ")
    for o in range(1, 8):
        print(f"{pulp.value(S[(p, o)]):.1f}", end=" ")
    print()

import pulp

# Data from the problem
trucks = ['T1', 'T2', 'T3', 'T4', 'T5', 'T6']
docks = ['D1', 'D2', 'D3', 'D4', 'D5', 'D6']

# Sequences: list of (dock, time) for each truck
sequences = {
    'T1': [('D5', 2), ('D6', 1), ('D1', 1), ('D2', 2), ('D4', 6), ('D3', 8)],
    'T2': [('D3', 4), ('D1', 3), ('D4', 9), ('D2', 9), ('D6', 2), ('D5', 9)],
    'T3': [('D2', 8), ('D1', 7), ('D6', 5), ('D3', 1), ('D4', 10), ('D5', 3)],
    'T4': [('D4', 2), ('D2', 10), ('D6', 7), ('D3', 6), ('D1', 4), ('D5', 9)],
    'T5': [('D4', 9), ('D1', 8), ('D6', 9), ('D3', 7), ('D5', 8), ('D2', 5)],
    'T6': [('D2', 8), ('D6', 2), ('D3', 2), ('D1', 8), ('D5', 7), ('D4', 10)]
}

# Extract processing times p[t][d]
processing_times = {t: {d: 0 for d in docks} for t in trucks}
for t in trucks:
    for dock, time in sequences[t]:
        processing_times[t][dock] = time

# Last dock for each truck
last_dock = {t: sequences[t][-1][0] for t in trucks}

# Big M: sum of all processing times + some buffer
M = sum(processing_times[t][d] for t in trucks for d in docks) + 100

# Model
model = pulp.LpProblem("TruckDockScheduling", pulp.LpMinimize)

# Decision variables
x = pulp.LpVariable.dicts("start", [(t, d) for t in trucks for d in docks], lowBound=0, cat='Continuous')
Cmax = pulp.LpVariable("Cmax", lowBound=0, cat='Continuous')

# Binary variables for precedence at each dock
y = {}
for d in docks:
    for i in range(len(trucks)):
        for j in range(i+1, len(trucks)):
            t1 = trucks[i]
            t2 = trucks[j]
            if processing_times[t1][d] > 0 and processing_times[t2][d] > 0:
                y[(t1, t2, d)] = pulp.LpVariable(f"y_{t1}_{t2}_{d}", cat='Binary')

# Objective: minimize makespan
model += Cmax

# Constraint 1: Cmax >= completion time of each truck
for t in trucks:
    last = last_dock[t]
    model += Cmax >= x[t, last] + processing_times[t][last]

# Constraint 2: Precedence within each truck's route
for t in trucks:
    seq = sequences[t]
    for idx in range(len(seq)-1):
        d1, time1 = seq[idx]
        d2, time2 = seq[idx+1]
        model += x[t, d2] >= x[t, d1] + time1

# Constraint 3: Disjunctive constraints for each dock
for d in docks:
    for i in range(len(trucks)):
        for j in range(i+1, len(trucks)):
            t1 = trucks[i]
            t2 = trucks[j]
            if processing_times[t1][d] > 0 and processing_times[t2][d] > 0:
                model += x[t2, d] >= x[t1, d] + processing_times[t1][d] - M * (1 - y[(t1, t2, d)])
                model += x[t1, d] >= x[t2, d] + processing_times[t2][d] - M * y[(t1, t2, d)]

# Solve
model.solve(pulp.HiGHS(msg=False, timeLimit=120))

# Output
print("Status:", pulp.LpStatus[model.status])
print("Optimal Makespan:", pulp.value(Cmax))
print("\nSchedule (start times at each dock):")
for t in trucks:
    print(f"{t}:", end="")
    for d in docks:
        if processing_times[t][d] > 0:
            print(f" {d}[{pulp.value(x[t, d]):.1f}]", end="")
    print()

print("\nDock occupancy (truck start → end):")
for d in docks:
    print(f"{d}:", end="")
    dock_trucks = []
    for t in trucks:
        if processing_times[t][d] > 0:
            dock_trucks.append((t, pulp.value(x[t, d]), pulp.value(x[t, d]) + processing_times[t][d]))
    # Sort by start time
    dock_trucks.sort(key=lambda v: v[1])
    for t, start, end in dock_trucks:
        print(f" {t}({start:.1f}-{end:.1f})", end="")
    print()

